  bkImpTemplate: async () => { if (!window.XLSX) return; const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([['Transaction Date', 'Value Date', 'Narration', 'Cheque No', 'UTR / Reference', 'Debit', 'Credit', 'Balance', 'Counterparty'], ['01-10-2026', '01-10-2026', 'NEFT CR XYZ SCHOOL FEES', '', 'UTR123456789', '', 25000, 18487300, 'XYZ'], ['02-10-2026', '02-10-2026', 'NEFT DR SECURE FACILITY SERVICES', '', 'UTR987654321', 185000, '', 18302300, 'Secure Facility Services'], ['03-10-2026', '03-10-2026', 'CLG CHQ 004512', '004512', '', 42000, '', 18260300, '']]), 'Statement'); XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([['Column', 'Required', 'Notes'], ['Transaction Date', 'Yes', 'DD-MM-YYYY or YYYY-MM-DD'], ['Value Date', 'No', ''], ['Narration', 'Yes', 'Bank description'], ['Cheque No', 'No', ''], ['UTR / Reference', 'Recommended', 'Used for reference matching'], ['Debit', 'One of Debit / Credit', 'Withdrawal'], ['Credit', 'One of Debit / Credit', 'Deposit'], ['Balance', 'No', 'Running balance'], ['Counterparty', 'No', 'Party name']]), 'Guide'); await saveFile('MSEA_Bank_Statement_Template.xlsx', new Blob([XLSX.write(wb, { bookType: 'xlsx', type: 'array' })])); },
  bkImpFile: t => { const file = t.files[0]; if (!file) return; const gl = bkGl(), a = bkAcct(gl), ext = (file.name.split('.').pop() || '').toLowerCase(); const rd = new FileReader(); rd.onload = () => { try { let rows, headers = null, map = null, format; if (['xlsx', 'xls', 'csv'].includes(ext)) { if (!window.XLSX) return toast('The Excel library did not load.', 'bad'); const wb = XLSX.read(new Uint8Array(rd.result), { type: 'array' }, evField()), ws = wb.Sheets[wb.SheetNames[0]], raw = XLSX.utils.sheet_to_json(ws, { defval: '', raw: false }); headers = raw.length ? Object.keys(raw[0]) : []; map = a.mapping && Object.values(a.mapping).every(h => headers.includes(h)) ? a.mapping : bkGuessMappingFor(headers, a); rows = bkRowsFromMapping(raw, map); format = ext === 'csv' ? 'CSV' : 'Excel (.xlsx)'; App.ui.bkRaw = raw; } else { const text = new TextDecoder().decode(new Uint8Array(rd.result)); if (/^:20:|:61:/m.test(text)) { rows = bkParseMT940(text); format = 'MT940'; } else if (/<Document|<Ntry/i.test(text)) { rows = bkParseCamt(text); format = 'CAMT.053 (XML)'; } else if (/<OFX|<STMTTRN/i.test(text)) { rows = bkParseOfx(text); format = 'OFX'; } else { rows = bkParsePdfText(text, a); if (!rows.length) rows = text.split(/\r?\n/).map(ln => ln.split(/[\t|,]/)).filter(c => c.length >= 4).map(c => ({ date: rmParseDate(c[0]), desc: c[1], ref: c[2], dr: rmAmt(c[3]), cr: rmAmt(c[4] || 0) })); format = /AXIS|UTIB/i.test(text) && bkBankCode(a) === 'AXIS' ? 'Axis statement (PDF / text)' : /ICICI|ICIC0/i.test(text) && bkBankCode(a) === 'ICICI' ? 'ICICI statement (PDF / text)' : 'PDF (converted)'; } } const lines = bkFinishLines(rows, gl, file.name, ''); App.ui.bkImp = { gl, file: file.name, format, headers, map, rows: lines, rejected: rows.length - lines.length }; App.ui.pc_bi = 'import'; rerender(); toast(`${lines.length} lines read (${format}).`); } catch (e) { console.error(e); toast('Could not read the statement: ' + e.message, 'bad'); } }; rd.readAsArrayBuffer(file); },
  bkMapCol: t => { const P = App.ui.bkImp; if (!P || !P.headers) return; P.map[t.dataset.k] = t.value; const rows = bkRowsFromMapping(App.ui.bkRaw || [], P.map); P.rows = bkFinishLines(rows, P.gl, P.file, ''); P.rejected = rows.length - P.rows.length; rerender(); },
