const BK_REPORTS = [
  ['brs', 'Bank Reconciliation Statement', () => { const gl = bkGl(), ym = bkPeriodYm(), asOf = ym === PROC_TODAY.slice(0, 7) ? PROC_TODAY : ym + '-31', R = bkBrs(gl, asOf, ym + '-01'), a = bkAcct(gl); const row = (k, vv, b) => `<tr class="${b ? 'tot' : ''}"><td>${k}</td><td class="n">${vv == null ? '—' : INR(vv)}</td></tr>`; return { html: `<div class="tbl-wrap compact"><table class="tbl"><thead><tr><th>${esc(a.bank)} · ${esc(a.acct)} · ${esc(a.entity)} · ${esc(fnBr(a.bid))} · ${a.currency} · ${rmPeriodLabel(ym)} (as of ${bkDate(asOf)})</th><th class="n">Amount</th></tr></thead><tbody>${row('Opening balance as per books (' + bkDate(ym + '-01') + ')', R.book0)}${row('Closing balance as per books', R.book1, true)}${row(`Add: payments / cheques recorded in books but not presented (${R.nUnpresented})`, R.unpresented)}${row(`Less: deposits recorded in books but not credited by bank (${R.nTransit})`, -R.inTransit)}${row('Add: interest and other direct credits in bank not yet in books', R.interest + R.otherCr)}${row('Less: bank charges, cheque returns and other direct debits not yet in books', -(R.charges + R.returns + R.otherDr))}${row('Adjusted balance as per books', R.adjBook, true)}${row('Closing balance as per bank statement', R.stmtBal, true)}<tr class="tot"><td><b>Difference</b></td><td class="n ${Math.abs(R.diff) > 1 ? 'red' : 'green'}"><b>${INR(R.diff)}</b></td></tr></tbody></table></div><p class="small muted">Available company-wise, bank-wise, branch-wise, currency-wise and date-wise through the account and period selectors. The cash-flow statement, bank GL balance and this statement read the same ledger.</p>`, cols: [{ h: 'Item', k: x => x.k, t: 'text' }, { h: 'Date', k: x => bkDate(x.d), t: 'text', x: x => x.d }, { h: 'Reference', k: x => x.ref, t: 'text', cls: 'small wrap' }, { h: 'Amount', k: x => x.amt, t: 'inr' }, { h: 'Days', k: x => Math.round((new Date(asOf) - new Date(x.d)) / 864e5), t: 'num' }], rows: [...bkBook(gl, '', asOf).filter(b => !b.recon).map(b => ({ k: b.cr ? 'Payment not presented' : 'Deposit not credited', d: b.date, ref: `${b.j.no} · ${b.mod} · ${b.j.narration.slice(0, 60)}`, amt: b.amt })), ...R.unm.map(l => ({ k: l.cr ? 'Bank credit not in books' : 'Bank debit not in books', d: l.date, ref: `${l.ref} · ${l.desc}`, amt: l.cr || l.dr }))].sort((x, y) => y.d.localeCompare(x.d)) }; }],
  ['balances', 'Bank balance vs book balance (all accounts)', () => ({ cols: [{ h: 'Account', k: a => `${a.gl} ${a.bank} ${a.acct.slice(-4)}`, t: 'text' }, { h: 'Entity · branch', k: a => `${a.entity} · ${fnBr(a.bid)}`, t: 'text', cls: 'small' }, { h: 'Currency', k: a => a.currency, t: 'text' }, { h: 'Book balance', k: a => bkBrs(a.gl, PROC_TODAY).book1, t: 'inr' }, { h: 'Statement balance', k: a => bkBrs(a.gl, PROC_TODAY).stmtBal || 0, t: 'inr' }, { h: 'Adjusted book', k: a => bkBrs(a.gl, PROC_TODAY).adjBook, t: 'inr' }, { h: 'Difference', k: a => bkBrs(a.gl, PROC_TODAY).diff, t: 'inr' }, { h: 'Completion %', k: a => { const S = bkAllLines().filter(l => l._bank === a.gl); return S.length ? S.filter(l => ['Reconciled', 'Matched', 'Approved', 'Interest', 'Bank Charges'].includes(l.status)).length / S.length * 100 : 100; }, t: 'pct' }, { h: 'Status', k: a => bkPill(a.status), t: 'html', x: a => a.status }], rows: BKM().accounts.filter(a => a.status === 'Active') })],
  ['completion', 'Reconciliation completion by bank and branch', () => { const m = {}; bkAllLines().forEach(l => { const k = l._bank; const o = m[k] = m[k] || { gl: k, n: 0, done: 0, amt: 0, unAmt: 0 }; o.n++; o.amt += l.cr + l.dr; if (['Reconciled', 'Matched', 'Approved', 'Interest', 'Bank Charges'].includes(l.status)) o.done++; else o.unAmt += l.cr + l.dr; }); const rows = Object.values(m); const br = {}; BKM().accounts.forEach(a => bkBook(a.gl, bkStart(a.gl)).forEach(b => { const k = b.l.bid || ''; const o = br[k] = br[k] || { bid: k, n: 0, done: 0, amt: 0 }; o.n++; o.amt += b.amt; if (b.recon) o.done++; })); return { html: table('bkCompBr', [{ h: 'Branch (book entries on bank accounts)', k: r => fnBr(r.bid), t: 'text' }, { h: 'Entries', k: r => r.n, t: 'num' }, { h: 'Reconciled', k: r => r.done, t: 'num' }, { h: 'Completion %', k: r => r.n ? r.done / r.n * 100 : 100, t: 'pct' }, { h: 'Amount', k: r => r.amt, t: 'inr' }], Object.values(br).sort((x, y) => (x.done / (x.n || 1)) - (y.done / (y.n || 1))), { compact: true, limit: 80, title: 'By branch' }), cols: [{ h: 'Bank', k: r => (bkAcct(r.gl) || {}).bank, t: 'text' }, { h: 'Statement lines', k: r => r.n, t: 'num' }, { h: 'Reconciled', k: r => r.done, t: 'num' }, { h: 'Completion %', k: r => r.n ? r.done / r.n * 100 : 100, t: 'pct' }, { h: 'Unreconciled amount', k: r => r.unAmt, t: 'inr' }, { h: 'Unreconciled count', k: r => r.n - r.done, t: 'num' }], rows }; }],
  ['inout', 'Daily bank inflow and outflow', () => { const gl = bkGl(), m = {}; bkAllLines().filter(l => l._bank === gl).forEach(l => { const o = m[l.date] = m[l.date] || { d: l.date, in: 0, out: 0, n: 0, bal: l.balance }; o.in += l.cr; o.out += l.dr; o.n++; o.bal = l.balance; }); return { cols: [{ h: 'Date', k: r => bkDate(r.d), t: 'text', x: r => r.d }, { h: 'Inflow', k: r => r.in, t: 'inr' }, { h: 'Outflow', k: r => r.out, t: 'inr' }, { h: 'Net', k: r => r.in - r.out, t: 'inr' }, { h: 'Transactions', k: r => r.n, t: 'num' }, { h: 'Closing balance', k: r => r.bal || 0, t: 'inr' }], rows: Object.values(m).sort((x, y) => y.d.localeCompare(x.d)) }; }],
  ['deposits', 'Collections deposited vs pending deposit', () => { const rows = DATA.branches.filter(b => !b.closed && (FN_CORP() || fnScope().has(b.id))).map(b => { const L = fnLines({ l: l => l.gl === '1101' && l.bid === b.id }); const coll = L.filter(x => x.l.dr).reduce((s, x) => s + x.l.dr, 0), dep = L.filter(x => x.l.cr).reduce((s, x) => s + x.l.cr, 0); const depJ = L.filter(x => x.l.cr && x.j.type === 'Cash deposit'); const rec = depJ.filter(x => x.j.recon).reduce((s, x) => s + x.l.cr, 0); return { b, coll, dep, pending: coll - dep, rec, unrec: depJ.reduce((s, x) => s + x.l.cr, 0) - rec }; }); return { cols: [{ h: 'Branch', k: r => r.b.name, t: 'text' }, { h: 'Cash collected (YTD)', k: r => r.coll, t: 'inr' }, { h: 'Deposited', k: r => r.dep, t: 'inr' }, { h: 'Pending deposit', k: r => r.pending, t: 'inr', rc: r => r.pending > BKM().cfg.autoApproveLimit / 2 ? 'red' : '' }, { h: 'Deposits reconciled with bank', k: r => r.rec, t: 'inr' }, { h: 'Deposits not yet credited', k: r => r.unrec, t: 'inr' }], rows: rows.sort((x, y) => y.pending - x.pending) }; }],
  ['vendor', 'Vendor payment reconciliation status', () => { const rows = []; BKM().accounts.forEach(a => bkBook(a.gl).filter(b => b.cr && /Vendor payment|Vendor advance|Utility payment|Payment$|Property tax payment|Maintenance/.test(b.j.type)).forEach(b => rows.push({ b, bank: a.bank }))); return { cols: [{ h: 'Date', k: r => bkDate(r.b.date), t: 'text', x: r => r.b.date }, { h: 'Voucher', k: r => r.b.j.no, t: 'text' }, { h: 'Source', k: r => r.b.mod, t: 'text' }, { h: 'Party', k: r => r.b.party, t: 'text' }, { h: 'Bank', k: r => r.bank, t: 'text', cls: 'small' }, { h: 'Amount', k: r => r.b.amt, t: 'inr' }, { h: 'Reconciled', k: r => bkPill(r.b.recon ? 'Reconciled' : 'Unreconciled'), t: 'html', x: r => r.b.recon ? 'Reconciled' : 'Unreconciled' }, { h: 'Days', k: r => r.b.recon ? 0 : Math.round((new Date(PROC_TODAY) - new Date(r.b.date)) / 864e5), t: 'num' }], rows: rows.sort((x, y) => y.b.date.localeCompare(x.b.date)) }; }],
  ['payroll', 'Payroll & statutory payment reconciliation status', () => { const rows = []; BKM().accounts.forEach(a => bkBook(a.gl).filter(b => /Salary payment|Statutory payment|SRF incentive payment/.test(b.j.type)).forEach(b => rows.push({ b, bank: a.bank }))); return { cols: [{ h: 'Date', k: r => bkDate(r.b.date), t: 'text', x: r => r.b.date }, { h: 'Voucher', k: r => r.b.j.no, t: 'text' }, { h: 'Kind', k: r => r.b.j.type, t: 'text' }, { h: 'Reference', k: r => r.b.doc, t: 'text', cls: 'small' }, { h: 'Bank', k: r => r.bank, t: 'text', cls: 'small' }, { h: 'Amount', k: r => r.b.amt, t: 'inr' }, { h: 'Reconciled', k: r => bkPill(r.b.recon ? 'Reconciled' : 'Unreconciled'), t: 'html', x: r => r.b.recon ? 'Reconciled' : 'Unreconciled' }], rows: rows.sort((x, y) => y.b.date.localeCompare(x.b.date)) }; }],
  ['cheques', 'Cheques issued, presented, stale and returned', () => { const cfg = BKM().cfg, rows = []; BKM().accounts.forEach(a => { bkBook(a.gl).filter(b => b.cr && /cheque|chq/i.test(b.j.narration + ' ' + b.j.type)).forEach(b => rows.push({ d: b.date, ref: b.j.no, party: b.party, bank: a.bank, amt: b.amt, st: b.recon ? 'Presented' : Math.round((new Date(PROC_TODAY) - new Date(b.date)) / 864e5) > cfg.staleChequeDays ? 'Stale' : 'Issued – not presented' })); bkAllLines().filter(l => l._bank === a.gl && (l.chq || /CHQ|CHEQUE/i.test(l.desc))).forEach(l => rows.push({ d: l.date, ref: l.chq || l.ref, party: l.party, bank: a.bank, amt: l.cr || l.dr, st: BK_RX_RTN.test(l.desc) || l.status === 'Returned' ? 'Returned' : l.cr ? 'Cleared (deposit)' : 'Presented' })); }); return { cols: [{ h: 'Date', k: r => bkDate(r.d), t: 'text', x: r => r.d }, { h: 'Cheque / voucher', k: r => r.ref, t: 'text' }, { h: 'Party', k: r => r.party, t: 'text' }, { h: 'Bank', k: r => r.bank, t: 'text', cls: 'small' }, { h: 'Amount', k: r => r.amt, t: 'inr' }, { h: 'Status', k: r => bkPill(r.st), t: 'html', x: r => r.st }], rows: rows.sort((x, y) => y.d.localeCompare(x.d)) }; }],
  ['charges', 'Bank charges and interest', () => { const rows = []; bkAllLines().forEach(l => { const c = l.category || bkClassify(l); if (c === 'Bank charges' || c === 'Interest') rows.push({ l, c }); }); return { cols: [{ h: 'Date', k: r => bkDate(r.l.date), t: 'text', x: r => r.l.date }, { h: 'Bank', k: r => (bkAcct(r.l._bank) || {}).bank, t: 'text' }, { h: 'Kind', k: r => r.c, t: 'text' }, { h: 'Narration', k: r => r.l.desc, t: 'text', cls: 'wrap small' }, { h: 'Charges', k: r => r.c === 'Bank charges' ? r.l.dr : 0, t: 'inr' }, { h: 'Interest', k: r => r.c === 'Interest' ? r.l.cr : 0, t: 'inr' }, { h: 'Accounted', k: r => bkPill(['Interest', 'Bank Charges', 'Reconciled'].includes(r.l.status) ? 'Posted' : 'Pending'), t: 'html', x: r => r.l.status }], rows }; }],
  ['entries', 'Direct bank entries created during reconciliation', () => ({ cols: [{ h: 'Entry', k: e => e.no, t: 'text' }, { h: 'Date', k: e => bkDate(e.date), t: 'text', x: e => e.date }, { h: 'Bank', k: e => (bkAcct(e.bank) || {}).bank, t: 'text' }, { h: 'Kind', k: e => e.kind, t: 'text' }, { h: 'Counter account', k: e => `${e.gl} ${fnGl(e.gl).name}`, t: 'text', cls: 'small' }, { h: 'Branch · cost centre', k: e => `${fnBr(e.bid)} · ${e.cc}`, t: 'text', cls: 'small' }, { h: 'Amount', k: e => e.amount, t: 'inr' }, { h: 'Maker', k: e => e.createdByName, t: 'text', cls: 'small' }, { h: 'Approver', k: e => (e.chain || []).filter(l => l.status === 'Approved').map(l => l.by).join(', '), t: 'text', cls: 'small' }, { h: 'Status', k: e => bkPill(e.status), t: 'html', x: e => e.status }], rows: BKT().entries })],
  ['ageing', 'Reconciliation ageing report', () => { const ex = bkExceptions(), m = {}; ex.forEach(x => { const k = `${x.bank}|${x.age}`; const o = m[k] = m[k] || { bank: x.bank, age: x.age, n: 0, amt: 0 }; o.n++; o.amt += x.amt; }); return { cols: [{ h: 'Bank', k: r => (bkAcct(r.bank) || {}).bank, t: 'text' }, { h: 'Ageing (days)', k: r => r.age, t: 'text' }, { h: 'Items', k: r => r.n, t: 'num' }, { h: 'Amount', k: r => r.amt, t: 'inr' }, { h: 'Escalation', k: r => (BKM().cfg.escalate.slice().reverse().find(e => parseInt(r.age.replace('>', '').split('–').pop()) >= e.days) || {}).to || '—', t: 'text' }], rows: Object.values(m).sort((x, y) => x.bank.localeCompare(y.bank) || parseInt(x.age.replace('>', '')) - parseInt(y.age.replace('>', ''))) }; }],
  ['users', 'User-wise reconciliation activity', () => { const m = {}; BKT().matches.forEach(x => { const o = m[x.createdByName] = m[x.createdByName] || { u: x.createdByName, matches: 0, amt: 0, approvals: 0, entries: 0, reversals: 0 }; o.matches++; o.amt += x.amount; (x.chain || []).filter(l => l.status === 'Approved').forEach(l => { const p = m[l.by] = m[l.by] || { u: l.by, matches: 0, amt: 0, approvals: 0, entries: 0, reversals: 0 }; p.approvals++; }); if (x.reversedBy) { const p = m[x.reversedBy] = m[x.reversedBy] || { u: x.reversedBy, matches: 0, amt: 0, approvals: 0, entries: 0, reversals: 0 }; p.reversals++; } }); BKT().entries.forEach(e => { const o = m[e.createdByName] = m[e.createdByName] || { u: e.createdByName, matches: 0, amt: 0, approvals: 0, entries: 0, reversals: 0 }; o.entries++; }); return { cols: [{ h: 'User', k: r => r.u, t: 'text' }, { h: 'Matches made', k: r => r.matches, t: 'num' }, { h: 'Amount matched', k: r => r.amt, t: 'inr' }, { h: 'Approvals', k: r => r.approvals, t: 'num' }, { h: 'Direct entries', k: r => r.entries, t: 'num' }, { h: 'Reversals', k: r => r.reversals, t: 'num' }], rows: Object.values(m).sort((x, y) => y.matches - x.matches) }; }],
  ['history', 'Prior-period reconciliation history & month comparison', () => { const rows = []; BKM().accounts.filter(a => a.status === 'Active').forEach(a => rmMonths('2026-04', 7).forEach(ym => { const P = bkPeriod(a.gl, ym), S = bkAllLines().filter(l => l._bank === a.gl && bkInRange(l.date, ym)); const asOf = ym === PROC_TODAY.slice(0, 7) ? PROC_TODAY : ym + '-31'; const R = S.length || ym >= '2026-09' ? bkBrs(a.gl, asOf, ym + '-01') : null; rows.push({ a, ym, P, n: S.length, done: S.filter(l => ['Reconciled', 'Matched', 'Approved', 'Interest', 'Bank Charges'].includes(l.status)).length, book: R ? R.book1 : fnBal(a.gl, { upto: asOf }), diff: R ? R.diff : 0, carried: P.carried || 0 }); })); return { cols: [{ h: 'Bank', k: r => r.a.bank, t: 'text' }, { h: 'Period', k: r => rmPeriodLabel(r.ym), t: 'text', x: r => r.ym }, { h: 'Status', k: r => bkPill(r.P.status), t: 'html', x: r => r.P.status }, { h: 'Submitted by', k: r => r.P.submittedBy || '', t: 'text', cls: 'small' }, { h: 'Approved by', k: r => r.P.approvedBy || '', t: 'text', cls: 'small' }, { h: 'Statement lines', k: r => r.n, t: 'num' }, { h: 'Reconciled', k: r => r.done, t: 'num' }, { h: 'Carried forward', k: r => r.carried, t: 'num' }, { h: 'Closing book balance', k: r => r.book, t: 'inr' }, { h: 'BRS difference', k: r => r.diff, t: 'inr' }, { h: '', k: r => ['Locked', 'Approved'].includes(r.P.status) && ['CFO', 'System Admin', 'Super Admin', 'Finance Admin'].includes(App.user.role) ? `<button class="btn sm ghost" data-act="bkReopenPeriod" data-k="${r.a.gl}|${r.ym}">Reopen</button>` : '', t: 'html', noexp: true }], rows }; }]
];
PAGES.br_reports = { title: 'BRS & Reconciliation Reports', mod: 'br_reports', group: true, render() {
  const key = BK_REPORTS.some(r => r[0] === App.ui.bkRep) ? App.ui.bkRep : 'brs', def = BK_REPORTS.find(r => r[0] === key); let R; try { R = def[2](); } catch (e) { console.error(e); return `<div class="note bad">${esc(e.message)}</div>`; }
  const rows = R.rows || [], NOSUM = /%|days|completion|closing|balance/i, totalVals = rows.length && R.cols ? R.cols.map(c => ['inr', 'num'].includes(c.t) && !NOSUM.test(c.h) ? rows.reduce((s, r) => { let x; try { x = c.x ? c.x(r) : c.k(r); } catch (e) { x = 0; } return s + (typeof x === 'number' && isFinite(x) ? x : 0); }, 0) : null) : null;
  const sel = `<label class="fld"><span>Report</span><select data-act="uiSel" data-k="bkRep">${BK_REPORTS.map(([k, l]) => `<option value="${k}" ${k === key ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select></label>${can('br_reports', 'Add') || can('br_admin', 'Edit') ? '<button class="btn sm" data-act="bkEmailNow">Email summary now</button>' : ''}`;
  return `${bkStrip(sel)}${card(def[1], (R.html || '') + (R.cols ? table('bkRep', R.cols, rows, { totalVals, compact: true, title: def[1], limit: 200, empty: 'No data.' }) : ''), { right: exportBtns('bkRep', 'br_reports'), sub: `Scheduled reports: daily → ${BKM().cfg.email.daily.join(', ') || '—'} · weekly → ${BKM().cfg.email.weekly.join(', ') || '—'} (${BKM().cfg.email.on ? 'on' : 'off'}) · Excel / PDF / CSV download` })}`;
} };
PAGES.br_admin = { title: 'Bank Reconciliation Control Centre', mod: 'br_admin', render() {
  const M = BKM(), c = M.cfg, ed = can('br_admin', 'Edit'), tab = pcTab('bra', 'rules'), num = (id, val) => `<input id="${id}" type="number" min="0" value="${val}" ${ed ? '' : 'disabled'}>`;
  const tabs = pcTabs('bra', [['rules', 'Matching rules & tolerances'], ['workflow', 'Approval workflow & controls'], ['periods', 'Period control'], ['alerts', 'Ageing, escalation & email reports']], 'rules');
  let body;
  if (tab === 'rules') body = table('bkRules', [{ h: 'Rule', k: r => r.id, t: 'text' }, { h: 'Matching rule', k: r => r.name, t: 'text' }, { h: 'Confidence weight', k: r => ed ? `<input id="bw_${r.id}" type="number" min="0" max="100" value="${r.weight}" style="width:80px">` : r.weight, t: 'html', x: r => r.weight }, { h: 'Active', k: r => bkPill(r.on ? 'Active' : 'Inactive') + (ed ? ` <button class="btn sm ghost" data-act="bkRuleTog" data-k="${r.id}">${r.on ? 'Disable' : 'Enable'}</button>` : ''), t: 'html', x: r => r.on ? 'Active' : 'Inactive' }], M.rules, { compact: true }) + `<div class="form-grid" style="margin-top:10px">${pcFld('Date tolerance (± days)', pcSel('bc_tol', ['1', '3', '7'], String(c.dateTol)) + pcFld('Date display format', pcSel('bc_datefmt', ['DD-MM-YYYY', 'D Mon YYYY'], c.dateFmt || 'DD-MM-YYYY')) + pcFld('Base currency · financial year', `<input value="${esc((c.currency || 'INR') + ' · ' + (c.fy || 'April – March'))}" disabled>`))}${pcFld('High confidence at or above (%)', num('bc_high', c.highAbove))}${pcFld('Medium confidence at or above (%)', num('bc_med', c.mediumAbove))}${pcFld('Auto-reconcile high-confidence matches', pcSel('bc_auto', [['1', 'Yes – within the auto-approve limit'], ['0', 'No – always review']], c.autoHigh ? '1' : '0'))}${pcFld('Auto-approve limit (₹)', num('bc_autolim', c.autoApproveLimit))}</div><p class="small muted">High: auto-matched subject to the approval rules · Medium: Finance user reviews and confirms · Low: stays unreconciled for manual action. The engine never posts or deletes entries on its own.</p>${ed ? '<button class="btn primary" data-act="bkCfgSave">Save</button>' : ''}`;
  else if (tab === 'workflow') body = `<div class="form-grid">${pcFld('Matches above need Finance Manager approval (₹)', num('bc_appr', c.approveAbove))}${pcFld('CFO / final approver above (₹)', num('bc_cfo', c.cfoAbove))}${pcFld('Stale cheque after (days)', num('bc_stale', c.staleChequeDays))}</div><p class="small">Workflow: Finance Executive / Accountant (maker) → Finance Manager → CFO / final approver; configurable by company, bank account, transaction type and amount in the Finance approval matrix (Finance control centre → Approval matrix, types <i>Bank adjustment</i> and <i>High-value payment</i>). Controls: no reconciled transaction can be edited or deleted – only reversed with reason, approval and audit log; closed periods are locked and reopened only by the CFO / System Admin; no user approves their own match or entry; separate permissions for import (br_import), matching (br_recon Edit / Post), direct entries (br_recon Post), approval (br_recon Approve), reversal (br_recon Reverse) and reports (br_reports); every change records user, time, old and new value, reason and approver.</p>${ed ? '<button class="btn primary" data-act="bkCfgSave">Save</button>' : ''}`;
  else if (tab === 'periods') { const rows = []; M.accounts.filter(a => a.status === 'Active').forEach(a => rmMonths('2026-04', 7).forEach(ym => rows.push({ a, ym, P: bkPeriod(a.gl, ym) }))); body = table('bkPer', [{ h: 'Bank', k: r => r.a.bank, t: 'text' }, { h: 'Period', k: r => rmPeriodLabel(r.ym), t: 'text', x: r => r.ym }, { h: 'Status', k: r => bkPill(r.P.status), t: 'html', x: r => r.P.status }, { h: 'By', k: r => r.P.by ? `${r.P.by} · ${tsLabel(r.P.at)}` : '', t: 'text', cls: 'small' }, { h: 'Reason', k: r => r.P.reason || '', t: 'text', cls: 'small wrap' }, { h: 'Carried forward', k: r => r.P.carried || 0, t: 'num' }, { h: '', k: r => ['Locked', 'Approved'].includes(r.P.status) && ['CFO', 'System Admin', 'Super Admin', 'Finance Admin'].includes(App.user.role) ? `<button class="btn sm ghost" data-act="bkReopenPeriod" data-k="${r.a.gl}|${r.ym}">Reopen</button>` : '', t: 'html', noexp: true }], rows, { compact: true, limit: 100 }) + (BKT().periodLog.length ? `<h4 class="blk">Period log</h4><ul class="small" style="padding-left:18px">${BKT().periodLog.slice(0, 15).map(l => `<li>${tsLabel(l.at)} · ${esc(l.by)} · ${esc(l.action)} ${rmPeriodLabel(l.p)} · ${l.bank === 'all' ? 'all banks' : esc((bkAcct(l.bank) || {}).bank || l.bank)} · ${esc(l.reason)}</li>`).join('')}</ul>` : '') + '<p class="small muted">Month-end: complete reconciliation for every account, submit for approval, lock after approval; unreconciled items carry forward automatically. The monthly P&L, cash flow and balance sheet close (General Ledger → Periods) checks that all bank accounts are reconciled.</p>'; }
  else body = `<div class="form-grid">${pcFld('Ageing buckets (days, 4 values)', `<input id="bc_age" value="${esc(c.ageBuckets.join(', '))}" ${ed ? '' : 'disabled'}>`)}${pcFld('Escalate to Finance Manager after (days)', num('bc_e1', c.escalate[0].days))}${pcFld('Escalate to CFO after (days)', num('bc_e2', c.escalate[1].days))}${pcFld('Escalate to CEO / management after (days)', num('bc_e3', c.escalate[2].days))}${pcFld('Scheduled email reports', pcSel('bc_mail', [['1', 'On (simulated)'], ['0', 'Off']], c.email.on ? '1' : '0'))}${pcFld('Daily report to (roles)', `<input id="bc_daily" value="${esc(c.email.daily.join(', '))}" ${ed ? '' : 'disabled'}>`)}${pcFld('Weekly report to (roles)', `<input id="bc_weekly" value="${esc(c.email.weekly.join(', '))}" ${ed ? '' : 'disabled'}>`)}</div>${ed ? '<button class="btn primary" data-act="bkCfgSave">Save</button> <button class="btn" data-act="bkEmailNow">Send summary now</button>' : ''}<h4 class="blk">Current escalations (${bkEscalations().length})</h4>` + table('bkEsc', [{ h: 'Escalate to', k: x => x.to, t: 'text' }, { h: 'Item', k: x => x.kind, t: 'text' }, { h: 'Bank', k: x => (bkAcct(x.bank) || {}).bank, t: 'text', cls: 'small' }, { h: 'Date', k: x => bkDate(x.date), t: 'text', x: x => x.date }, { h: 'Reference', k: x => x.ref, t: 'text', cls: 'small' }, { h: 'Amount', k: x => x.amt, t: 'inr' }, { h: 'Days', k: x => x.days, t: 'num' }], bkEscalations(), { compact: true, limit: 50, empty: 'Nothing escalated.' });
  return card('Bank Reconciliation Control Centre', tabs + body, { sub: 'Configurable rules, tolerances, approval limits, ageing and escalation – every change is logged with the reason.' });
} };
